# Expand banks by importing from hand_expand and scenes - dedupe
import importlib.util, sys
sys.path.insert(0, str(Path(__file__).parent.parent.parent))
from hand_expand_vol4_19_21 import CH19_PARAS, CH20_PARAS, CH21_PARAS

def merge(*groups):
    import hashlib, re
    seen = set()
    out = []
    for group in groups:
        for p in group:
            k = hashlib.md5(re.sub(r"\s+", "", p).encode()).hexdigest()
            if k not in seen:
                seen.add(k)
                out.append(p)
    return out

def load_mod(path, attr=None):
    spec = importlib.util.spec_from_file_location(path.stem, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    if attr:
        return getattr(mod, attr)
    out = []
    for a in dir(mod):
        if a.startswith(("BANK", "EXTRA", "SCENES", "SUPP", "UNIQUE")):
            v = getattr(mod, a)
            if isinstance(v, list):
                out.extend(v)
    return out

extras19 = []
extras20 = []
extras21 = []
HERE = Path(__file__).resolve().parent
SKIP = {"generate_banks.py", "p19.py", "p20.py", "p21.py", "extra2_ch19.py"}
for fname in HERE.glob("*.py"):
    if fname.name in SKIP:
        continue
    if "ch19" in fname.name or fname.name == "scenes_19.py" or fname.name == "scenes_ch19.py":
        extras19.extend(load_mod(fname))
    elif "ch20" in fname.name or fname.name == "scenes_20.py":
        extras20.extend(load_mod(fname))
    elif "ch21" in fname.name or fname.name == "scenes_21.py":
        extras21.extend(load_mod(fname))

P19 = merge(P19, CH19_PARAS, extras19)
P20 = merge(P20, CH20_PARAS, extras20)
P21 = merge(P21, CH21_PARAS, extras21)

for name, bank in [("p19", P19), ("p20", P20), ("p21", P21)]:
    (HERE / f"{name}.py").write_text(
        f"BANK = [\n" + "\n".join(f'    """{p}""",' for p in bank) + "\n]\n",
        encoding="utf-8",
    )
    print(f"{name}.py\t{len(bank)}\t{sum(len(p) for p in bank)}")